using UnityEngine;
using UnityEditor;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var uxml = AssetDatabase.LoadAssetAtPath<VisualTreeAsset>("Assets/Resources/HUDTree/HudUI_kit.uxml.meta");
        // Real path doesn't have .meta - try without:
        if (uxml == null)
        {
            uxml = AssetDatabase.LoadAssetAtPath<VisualTreeAsset>("Assets/Resources/HUDTree/HUDOverlay_kit.uxml");
            result.Log("HUDOverlay_kit.uxml -> " + (uxml == null ? "NULL" : "Loaded ok"));
        }
        var uss = AssetDatabase.LoadAssetAtPath<StyleSheet>("Assets/Resources/HUDTree/HudUI_kit.uss");
        result.Log("HudUI_kit.uss -> " + (uss == null ? "NULL" : "Loaded ok"));
        var overlay = AssetDatabase.LoadAssetAtPath<VisualTreeAsset>("Assets/Resources/HUDTree/HUDOverlay_kit.uxml");
        result.Log("HUDOverlay_kit.uxml -> " + (overlay == null ? "NULL" : "Loaded ok"));
        var btnAtlas = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/HUDTree/Atlases/Kit/button_atlas_kit.png");
        result.Log("Kit/button_atlas_kit.png -> " + (btnAtlas == null ? "NULL" : (btnAtlas.width + "x" + btnAtlas.height)));
        var vital = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Resources/HUDTree/Atlases/Kit/vital_atlas_kit.png");
        result.Log("Kit/vital_atlas_kit.png -> " + (vital == null ? "NULL" : (vital.width + "x" + vital.height)));
    }
}
